import {normalizeRow,todayIST,messageFor,validateTemplate} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], key='usha-one-reminders-demo-v1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(x);
const date=x=>new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date(x));
const defaultSettings={business_name:'USHA ONE Technologies',paused:true,template:'నమస్కారం {name} గారు. {business} నుంచి గుర్తు చేస్తున్నాము. మీరు చెల్లించవలసిన మొత్తం {amount} రూపాయలు. గడువు తేదీ {due_date}. ఇప్పటికే చెల్లించి ఉంటే ఈ సందేశాన్ని విస్మరించండి. ధన్యవాదాలు.'};
let state,filter='all',view='overview',connection=null,health=null,offset=0,preview=[],toastTimer;
function seed(){const today=todayIST(),y=new Date();y.setDate(y.getDate()-2);const older=todayIST(y);const names=['Sample · Ananya Rao','Sample · Ravi Kumar','Sample · Priya Reddy','Sample · Suresh Patel','Sample · Meera Shah'];const dues=names.map((name,i)=>({id:crypto.randomUUID(),reference:'DEMO-2026-00'+(i+1),amount:[8500,12000,4500,6750,3200][i],due_date:i===1?older:today,state:i===2?'paid':i===4?'paused':'pending',vr_customers:{id:crypto.randomUUID(),name,phone:'+91900000000'+i,consent:true}}));return {dues,settings:{...defaultSettings},attempts:[{id:crypto.randomUUID(),due_id:dues[2].id,status:'completed',created_at:new Date().toISOString(),call_sid:'Demo · no call made'},{id:crypto.randomUUID(),due_id:dues[1].id,status:'no-answer',created_at:new Date().toISOString(),call_sid:'Demo · no call made'}]};}
function loadDemo(){try{state=JSON.parse(localStorage.getItem(key))||seed();if(!Array.isArray(state.dues)||!state.settings)state=seed();}catch{state=seed();}}
function persist(){if(!connection){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Browser storage is unavailable; changes last until this page closes.');}}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
async function api(path,method='GET',body){const r=await fetch(connection.url+path,{method,headers:{Authorization:'Bearer '+connection.token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});const data=await r.json().catch(()=>({error:'Backend did not return JSON'}));if(!r.ok)throw Error(data.error||'Request failed');return data;}
async function refresh(){if(connection)state=await api('/api/dashboard?offset='+offset);render();}
function changeView(next){view=next;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#overview-top').hidden=view!=='overview';$('#customer-panel').hidden=!['overview','customers'].includes(view);$('#activity-panel').hidden=view!=='activity';$('#voice-panel').hidden=view!=='voice';$('#page-title').textContent={overview:'Every reminder. Taken care of.',customers:'The right follow-up starts here.',activity:'Every call, in clear view.',voice:'Make every reminder your own.'}[view];$('#page-subtitle').textContent={overview:'A clear view of your dues, customers and Telugu voice reminders.',customers:'Manage customer dues, consent and payment status in one place.',activity:'Track delivery without confusing a completed call with a paid invoice.',voice:'A personalized Telugu message and a schedule that works for you.'}[view];render();}
function render(){
 const dues=state.dues,attempts=state.attempts;
 $('#outstanding').textContent=money(dues.filter(d=>d.state!=='paid').reduce((s,d)=>s+Number(d.amount),0));
 $('#due-count').textContent=dues.filter(d=>d.state==='pending'&&d.due_date<=todayIST()&&d.vr_customers.consent).length;
 $('#completed-count').textContent=attempts.filter(a=>a.status==='completed').length;
 $('#attention-count').textContent=attempts.filter(a=>['busy','no-answer','failed','uncertain'].includes(a.status)).length;
 $('#schedule-badge').textContent=state.settings.paused?'Paused':connection?'Enabled':'Demo enabled';
 $('#pause-schedule').textContent=state.settings.paused?'Enable schedule':'Pause schedule';
 const q=$('#search').value.toLowerCase();const visible=dues.filter(d=>(filter==='all'||(filter==='due'?d.state==='pending'&&d.due_date<=todayIST():d.state===filter))&&[d.vr_customers.name,d.vr_customers.phone,d.reference].some(x=>x.toLowerCase().includes(q)));
 $('#rows').innerHTML=visible.map(d=>{const c=d.vr_customers;return `<tr><td><div class="person"><span class="avatar">${esc(c.name.replace('Sample · ','').split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><b>${esc(c.name)}</b><small>${esc(c.phone)}${c.consent?'':' · No consent'}</small></div></div></td><td>${esc(d.reference)}</td><td class="money">${money(d.amount)}</td><td>${date(d.due_date)}</td><td><span class="badge status ${d.state}">${d.state==='pending'?'Pending':d.state==='paid'?'Paid':'Paused'}</span></td><td>${d.state!=='paid'?`<button class="row-action" data-id="${d.id}" data-state="paid">Mark paid</button><button class="row-action" data-id="${d.id}" data-state="${d.state==='paused'?'pending':'paused'}">${d.state==='paused'?'Resume':'Pause'}</button>`:'<span class="badge paid">Settled</span>'}<button class="row-action" data-consent="${c.id}" data-value="${!c.consent}">${c.consent?'Revoke consent':'Record consent'}</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No matching dues. Add a customer or import your spreadsheet.</td></tr>';
 $('#row-count').textContent=`${visible.length} of ${dues.length} records${connection?' · page '+(offset/500+1):' · demo data'}`;
 $('#prev').hidden=!connection||offset===0;$('#next').hidden=!connection||dues.length<500;
 $('#logs').innerHTML=attempts.map(a=>{const d=dues.find(x=>x.id===a.due_id);return `<tr><td>${esc(d?.vr_customers.name||a.due_id)}<br><small>${esc(d?.reference||'Record on another page')}</small></td><td>${new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}).format(new Date(a.created_at))}</td><td><span class="badge status ${esc(a.status)}">${a.status==='uncertain'?'Needs review':esc(a.status)}</span></td><td>${esc(a.call_sid||'Not assigned')}${a.error_code?'<br><small>'+esc(a.error_code)+'</small>':''}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">No calls yet. Attempts will appear here after calling is configured.</td></tr>';
 $('#voice-form').elements.business_name.value=state.settings.business_name;$('#voice-form').elements.template.value=state.settings.template;
 const example=dues[0]||{amount:1000,due_date:todayIST(),vr_customers:{name:'కస్టమర్'}};
 $('#voice-preview').textContent=messageFor({...example.vr_customers,...example},state.settings);
 $('#banner').classList.toggle('live',!!connection);
 $('#banner').firstElementChild.textContent=connection?`Connected workspace · Calling: ${health.mode} · Database: ${health.database?'configured':'not connected'} · Voice: ${health.voice?'configured':'not connected'}`:'Demo workspace · Sample data only. Changes stay in this browser; no calls are made.';
 $('#reset').hidden=!!connection;$('#connect').textContent=connection?'Connection settings ↗':'Connect backend ↗';
}
async function saveRows(rows){if(connection){const result=await api('/api/import','POST',{rows});await refresh();return result;}let inserted=0;for(const r of rows){if(state.dues.some(d=>d.reference===r.reference))continue;const customer=state.dues.find(d=>d.vr_customers.phone===r.phone)?.vr_customers||{id:crypto.randomUUID(),name:r.name,phone:r.phone,consent:r.consent};state.dues.unshift({id:crypto.randomUUID(),reference:r.reference,amount:r.amount,due_date:r.due_date,state:'pending',vr_customers:customer});inserted++;}persist();render();return {inserted,skipped:rows.length-inserted};}
$$('.nav').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$('#review-voice').onclick=()=>changeView('voice');$('#search').oninput=render;
$('#filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;$$('#filters button').forEach(x=>x.classList.toggle('selected',x===b));render();};
$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#add').onclick=()=>{$('#entry-form').reset();$('#entry-form').elements.due_date.value=todayIST();$('#entry-dialog .form-error').textContent='';$('#entry-dialog').showModal();};
$('#import').onclick=()=>$('#import-dialog').showModal();$('#connect').onclick=()=>{$('#connect-form').elements.url.value=connection?.url||location.origin;$('#connect-form .form-error').textContent='';$('#connect-dialog').showModal();};
$('#entry-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit],button.full');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.consent=e.target.elements.consent.checked;const result=await saveRows([normalizeRow(data)]);$('#entry-dialog').close();toast(result.inserted?'Customer due saved.':'Reference already exists. Nothing changed.');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}};
$('#rows').onclick=async e=>{const b=e.target.closest('button');if(!b)return;b.disabled=true;try{if(b.dataset.consent){const consent=b.dataset.value==='true';if(!confirm(consent?'Confirm this customer has agreed to voice reminders?':'Stop future voice reminders for this customer?'))return;if(connection)await api('/api/customers/'+b.dataset.consent+'/consent','PATCH',{consent});else state.dues.forEach(d=>{if(d.vr_customers.id===b.dataset.consent)d.vr_customers.consent=consent;});}else{if(b.dataset.state==='paid'&&!confirm('Mark this invoice as paid? This stops future reminders.'))return;if(connection)await api('/api/dues/'+b.dataset.id,'PATCH',{state:b.dataset.state});else state.dues.find(d=>d.id===b.dataset.id).state=b.dataset.state;}persist();await refresh();toast('Record updated.');}catch(err){toast(err.message);}finally{b.disabled=false;}};
$('#reset').onclick=()=>{if(confirm('Reset this demo and remove its locally saved records?')){state=seed();persist();render();toast('Demo reset.');}};
$('#refresh').onclick=()=>refresh().catch(e=>toast(e.message));$('#next').onclick=async()=>{offset+=500;try{await refresh();}catch(e){offset-=500;toast(e.message);}};$('#prev').onclick=async()=>{offset=Math.max(0,offset-500);await refresh().catch(e=>toast(e.message));};
function download(name,text){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(x){const s=String(x??'');return '"'+(/^[=+@\-\t\r]/.test(s)?"'"+s:s).replaceAll('"','""')+'"';}
$('#template').onclick=()=>download('usha-one-import-template.csv','name,phone,reference,amount,due_date,consent\r\nSample Customer,9000000000,INV-001,1500.00,'+todayIST()+',no\r\n');
$('#export').onclick=()=>download('usha-one-dues.csv',[['name','phone','reference','amount','due_date','state','consent'],...state.dues.map(d=>[d.vr_customers.name,d.vr_customers.phone,d.reference,d.amount,d.due_date,d.state,d.vr_customers.consent])].map(r=>r.map(csvCell).join(',')).join('\r\n'));
$('#file').onchange=async e=>{preview=[];$('#save-import').disabled=true;$('#import-dialog .form-error').textContent='';$('#import-rows').innerHTML='';try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('File exceeds 2 MB');if(!/\.(xlsx|csv)$/i.test(file.name))throw Error('Choose .xlsx or .csv');if(!window.XLSX)throw Error('Spreadsheet reader unavailable. Reload this page.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,sheetRows:502});const matrix=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{header:1,defval:'',raw:true,blankrows:false});if(matrix.length<2||matrix.length>501)throw Error('Use 1–500 data rows');const headers=matrix[0].map(x=>String(x).trim().toLowerCase());for(const h of ['name','phone','reference','amount','due_date','consent'])if(!headers.includes(h))throw Error('Missing column: '+h);if(new Set(headers).size!==headers.length)throw Error('Duplicate column headers');const seen=new Set();preview=matrix.slice(1).map((values,i)=>{const obj=Object.fromEntries(headers.map((h,j)=>[h,values[j]??'']));if(obj.due_date instanceof Date)obj.due_date=[obj.due_date.getFullYear(),String(obj.due_date.getMonth()+1).padStart(2,'0'),String(obj.due_date.getDate()).padStart(2,'0')].join('-');try{const row=normalizeRow(obj);if(seen.has(row.reference))throw Error('Duplicate reference in file');seen.add(row.reference);return {index:i+2,row};}catch(err){return {index:i+2,row:obj,error:err.message};}});const invalid=preview.filter(p=>p.error).length;$('#import-summary').textContent=`${preview.length} rows · ${invalid} need correction${invalid?' · Fix errors and upload again':''}`;$('#import-rows').innerHTML=preview.map(p=>`<tr><td>${p.index}</td><td>${esc(p.row.name)}</td><td>${esc(p.row.reference)}</td><td>${esc(p.error||'Ready'+(p.row.consent?'':' · No calling consent'))}</td></tr>`).join('');$('#save-import').disabled=!!invalid;}catch(err){$('#import-dialog .form-error').textContent=err.message;}};
$('#save-import').onclick=async()=>{const b=$('#save-import');b.disabled=true;try{const r=await saveRows(preview.map(p=>p.row));$('#import-dialog').close();toast(`${r.inserted} imported; ${r.skipped} existing references skipped.`);preview=[];$('#file').value='';$('#import-summary').textContent='';$('#import-rows').innerHTML='';}catch(err){$('#import-dialog .form-error').textContent=err.message;b.disabled=false;}};
$('#voice-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));data.template=validateTemplate(data.template);if(connection)await api('/api/settings','PATCH',data);else Object.assign(state.settings,data);persist();await refresh();toast('Message saved.');}catch(err){toast(err.message);}};
$('#pause-schedule').onclick=async()=>{const paused=!state.settings.paused;if(!paused&&!confirm(connection?'Enable scheduled customer calls? Confirm your voice setup has passed a test call.':'Enable the simulated schedule? No real calls will be made.'))return;try{if(connection)await api('/api/settings','PATCH',{paused});else state.settings.paused=paused;persist();await refresh();toast(paused?'Schedule paused.':connection?'Schedule enabled.':'Demo schedule enabled. No calls are made.');}catch(e){toast(e.message);}};
$('#listen').onclick=()=>{if(!('speechSynthesis'in window))return toast('Speech preview is not available on this browser.');const voice=speechSynthesis.getVoices().find(v=>/^te[-_]/i.test(v.lang));if(!voice)return toast('No Telugu voice installed on this device. Read the preview or test through Twilio after setup.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance($('#voice-preview').textContent);u.lang='te-IN';u.voice=voice;speechSynthesis.speak(u);};
$('#connect-form').onsubmit=async e=>{e.preventDefault();const old=connection;try{const url=new URL(e.target.elements.url.value);if(url.protocol!=='https:'||url.username||url.password||url.pathname!=='/'||url.search||url.hash)throw Error('Use an HTTPS origin only, without a path or credentials');connection={url:url.origin,token:e.target.elements.token.value};const result=await api('/api/health');if(!result.database)throw Error('Backend found, but database secrets are missing');health=result;offset=0;await refresh();e.target.elements.token.value='';$('#connect-dialog').close();toast('Connected. Shared records loaded.');}catch(err){connection=old;e.target.querySelector('.form-error').textContent=err.message;}};
$('#disconnect').onclick=()=>{connection=null;health=null;offset=0;$('#connect-form').elements.token.value='';loadDemo();render();$('#connect-dialog').close();toast('Returned to demo.');};
loadDemo();render();
